/// miss is not consent, full stop.** The attacker cannot make this function return `None` for an identity this
/// machine actually minted — reaching `<state_root>/adoption-floors/` to remove or edit the entry is exactly the
/// privilege the AR88 repair already establishes they do not have.
///
/// A plain directory scan (never indexed, never large — this machine's own local floor store, one entry per
/// checkout this machine has ever onboarded) is what makes this a decision on evidence rather than on the key's
/// own absence.
fn other_live_claim(state_root: &Path, identity: &str, current_canon: &str) -> Option<String> {
    let dir = state_root.join("adoption-floors");
    let Ok(entries) = std::fs::read_dir(&dir) else {
        return None;
    };
    for entry in entries.filter_map(|e| e.ok()) {
        let Ok(v) = crate::util::read_json(&entry.path().join("identity.json")) else {
            continue; // no identity.json in this entry, or it does not parse -- not a match either way
        };
        if v.get("project_identity").and_then(|x| x.as_str()) != Some(identity) {
            continue;
        }
        let Some(minted_for) = v.get("minted_for_path").and_then(|x| x.as_str()) else {
            continue; // written before this field existed -- nothing to compare against
        };
        // P2-AR-0093 (AR92-C1/C1B/C1C): NO liveness test here, on purpose -- see this function's own doc. An
        // entry this machine holds for `identity` is evidence regardless of what the filesystem, which the party
        // being checked may control, currently reports about the path it names.
        if minted_for != current_canon {
            return Some(minted_for.to_string());
        }
    }
    None
}

impl FloorIdentity {
    /// The machine-protected anchor file for THIS checkout, or `None` inside an OS-created health sandbox (never
    /// persisted — see [`is_health_sandbox_root`] and [`FloorIdentity`]'s own doc on why that is safe). Fails
    /// (also `None`) only if the protected state root itself cannot be resolved — an SRR/Level-1 concern this
    /// module does not own; every caller already treats "no local ledger" as the legitimate bootstrap case.
    fn path(root: &Path) -> Option<PathBuf> {
        let state_root = crate::srr::state::resolve_state_root().ok()?;
        anchor_path_under(&state_root, root)
    }
    fn read_full(root: &Path) -> Option<FloorIdentityState> {
        parse_floor_identity_state(&crate::util::read_json(&Self::path(root)?).ok()?)
    }
    /// The identity and highest sequence this CHECKOUT has itself established or observed, if any.
    fn read(root: &Path) -> Option<(String, u64)> {
        Self::read_full(root).map(|s| (s.project_identity, s.max_known_sequence))
    }
    /// **P2-AR-0095 (AR94-C3), corrected; the motivating caller deleted whole by P2-AR-0096.** Used to return
    /// `Ok(())` without writing anything when [`Self::path`] is `None` (inside an OS-created health sandbox), on
    /// the theory that callers treat "no local ledger" as a legitimate no-op there. That theory held for every
    /// caller of this crate EXCEPT `reanchor_project_identity` (P2-AR-0093 §1.3, deleted whole by P2-AR-0096 —
    /// see `RESEARCH/P2-PROBE-OPTION-C.md`), which called this directly to perform a DESTRUCTIVE move: it followed
    /// this call with an unconditional `remove_dir_all` of the OLD entry's directory, so a silent `Ok(())` here
    /// let that deletion proceed while reporting success for a write that never happened. That caller is gone, but
    /// the typed refusal stays: it is the defence this function owes its OWN contract regardless of whether the
    /// current caller set already avoids the case — a function that reports success for work it did not do is a
    /// defect wherever it appears, and silently swallowing "nothing was written" is exactly how the original
    /// defect stayed invisible. [`Self::write`]/[`Self::advance`] never run against a sandboxed root in practice
    /// (onboarding and reclassification are not reachable from inside a health check); the one remaining caller,
    /// [`Self::remember_rules`], is guarded by its own `read_full` short-circuit, which itself returns `None` for
    /// a sandboxed root before this could be reached — so no current caller exercises this path at all; it is
    /// deliberately kept anyway, unreachable-but-correct, rather than removed along with its former caller.
    fn write_full(root: &Path, s: &FloorIdentityState) -> Result<()> {
        let Some(p) = Self::path(root) else {
            return Err(GovError::new(
                "FLOOR_IDENTITY_WRITE_INSIDE_SANDBOX_EXEMPTION",
                "no machine-store identity entry can be written for an OS-created health sandbox (FloorIdentity::\
                 path returns None for one by design) -- refusing instead of silently reporting success for a \
                 write that did not happen",
            ));
        };
        crate::srr::state::write_durable(
            &p,
            &json!({"schema_version": "1.2.0", "project_identity": s.project_identity,
                     "max_known_sequence": s.max_known_sequence, "last_known_rules": s.last_known_rules,
                     "minted_for_path": s.minted_for_path, "bootstrap_adopted": s.bootstrap_adopted}),
        )
    }
    /// **P2-AR-0091.** `minted_for_path` is set ONCE, from this checkout's own already-established record if one
    /// exists (a sequence advance must never move where an identity is on record as belonging to), or from this
    /// checkout's CURRENT canonical path otherwise — the first-ever write for a fresh identity (genuine onboarding)
    /// and the bootstrap-adopt write in [`FloorIdentity::reconcile`] (a genuine relocation or foreign clone) are
    /// both "this identity now belongs here", so both mint it. `bootstrap` is `true` ONLY from that one
    /// [`FloorIdentity::reconcile`] call site — see [`FloorIdentityState::bootstrap_adopted`]'s own doc; `false`
    /// here never clears an already-`true` record (an ordinary LATER advance of an identity that WAS originally
    /// bootstrap-adopted must not quietly erase that provenance).
    fn write(root: &Path, project_identity: &str, max_known_sequence: u64, bootstrap: bool) -> Result<()> {
        let prev = Self::read_full(root);
        let last_known_rules = prev.as_ref().map(|s| s.last_known_rules.clone()).unwrap_or_default();
        let bootstrap_adopted = bootstrap || prev.as_ref().map(|s| s.bootstrap_adopted).unwrap_or(false);
        let minted_for_path = prev
            .map(|s| s.minted_for_path)
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| canonical_path_string(root));
        Self::write_full(
            root,
            &FloorIdentityState {
                project_identity: project_identity.to_string(),
                max_known_sequence,
                last_known_rules,
                minted_for_path,
                bootstrap_adopted,
            },
        )
    }
    /// Called by [`write_project_adoption_floor`] immediately before it writes a new floor document: the identity
    /// this checkout has already established (never re-minted), or a freshly minted one if this is the FIRST floor
    /// this checkout has ever written; and the next sequence number. Persists the advance before returning it, so a
    /// crash between this call and the floor write leaves the local ledger AHEAD of the document rather than
    /// behind it (a skipped sequence number is harmless; a document sequence this ledger has not yet recorded would
    /// not be). Always `bootstrap: false` — this is this checkout's OWN authoring, through onboarding or a governed
    /// reclassification, never a document-claim adoption.
    fn advance(root: &Path) -> Result<(String, u64)> {
        let (identity, prev_seq) = Self::read(root)
            .unwrap_or_else(|| (uuid::Uuid::new_v4().to_string(), 0));
        let seq = prev_seq + 1;
        Self::write(root, &identity, seq, false)?;
        Ok((identity, seq))
    }
    /// Called by [`write_project_adoption_floor`] right after a successful write, and by
    /// [`read_project_adoption_floor`] right after a floor fully verifies: `rules` is now this checkout's own
    /// record of the last AUTHENTICATED floor, independent of whatever the document on disk says later. Never
    /// clears a previously remembered set to empty (an empty `rules` here is the no-op write short-circuit in
    /// [`write_project_adoption_floor`], not a legitimate "the floor is now nothing").
    fn remember_rules(root: &Path, rules: &[Value]) {
        if rules.is_empty() {
            return;
        }
        let Some(mut s) = Self::read_full(root) else {
            return; // no identity established yet -- `advance`/`reconcile` always run first and create it
        };
        s.last_known_rules = rules.to_vec();
        let _ = Self::write_full(root, &s);
    }
    /// Called by [`read_project_adoption_floor`]: reconcile this checkout's local ledger against a floor document
    /// that verified its T2 seal and whose git-lineage binding already matched. `Ok(())` when the document may be
    /// honoured; `Err` names the mismatch. A fresh checkout with no local ledger yet (a legitimate `git clone`,
    /// P2-ADJ-0002) ADOPTS the document's own claim as its baseline rather than refusing it — there is nothing
    /// locally established yet to contradict it, and this is exactly the bootstrap a portable T2 seal already
    /// relies on machine-wide; a checkout that already has a ledger (this repository's own original checkout,
    /// after its own onboarding) never bootstraps again.
    ///
    /// **P2-AR-0091 (AR90-C1/C1B/C1C/C1D/C2): a key MISS is not consent.** Before this repair, "no local ledger
    /// yet" was treated as ALWAYS meaning "a fresh checkout" — but [`floor_anchor_key`] no longer folds in
    /// repository lineage, and a checkout's own canonical path can itself be evicted from under it (an orphan
    /// commit did not change the key before either; a relocation legitimately does). [`other_live_claim`] is
    /// consulted first: if THIS machine already minted the document's claimed identity for a DIFFERENT path,
    /// **whether or not that path still exists (P2-AR-0093, AR92-C1/C1B/C1C)**, the miss is an eviction, not a
    /// fresh checkout, and is refused rather than adopted — **permanently, by construction (P2-AR-0096): nothing
    /// ever moves an existing entry again**, whether this checkout is a genuine relocation of that other one or an
    /// ordinary second working copy of the same repository. Both read identically here, and — since deleting
    /// `gov floor-reanchor` removed the one operation that used to distinguish their remedies by TRANSFERRING the
    /// identity — both now have the SAME remedy: a fresh, governed re-onboarding (`gov init --force`, or
    /// `gov adopt`) mints THIS checkout its own new identity, never touching the entry this refusal names. Skipped
    /// entirely inside an OS-created health sandbox ([`is_health_sandbox_root`]) — a sandbox's byte-copied floor
    /// legitimately names the SAME identity as the live project it was copied from, which is always still there;
    /// the sandbox exemption already established that a never-reused key bootstraps regardless, and this check
    /// must not silently take that back.
    fn reconcile(root: &Path, doc_identity: Option<&str>, doc_sequence: u64) -> std::result::Result<(), String> {
        let Some(doc_identity) = doc_identity else {
            return Err("carries no project-identity binding at all (written before this repair)".to_string());
        };
        match Self::read(root) {
            None => {
                let current = canonicalize_or(root);
                let state_root = crate::srr::state::resolve_state_root().ok();
                let sandboxed = state_root
                    .as_deref()
                    .map(|sr| is_health_sandbox_root(sr, &current))
                    .unwrap_or(false);
                if !sandboxed {
                    if let Some(sr) = &state_root {
                        if let Some(other) =
                            other_live_claim(sr, doc_identity, &current.to_string_lossy())
                        {
                            return Err(format!(
                                "bound_project_identity {doc_identity:?} was already minted by THIS machine for a \
                                 DIFFERENT project still recorded at {other:?}: no local ledger exists yet for \
                                 THIS checkout's own path, but a key miss is not consent -- the identity belongs to \
                                 that other checkout, not to this one, whether or not that other path still exists \
                                 (P2-AR-0091/P2-AR-0093, AR90-C1/C1B/C1C/C1D/C2, AR92-C1/C1B/C1C). This is either a \
                                 genuine relocation of that other checkout, or an ordinary second, still-live \
                                 working copy of the same repository (a second checkout on this machine, or a \
                                 teammate's clone) -- both read identically here, and, since P2-AR-0096, both have \
                                 the SAME remedy: re-run governed onboarding at THIS checkout's own current path \
                                 (`gov init --force`, or a fresh `gov adopt`), which mints this checkout its OWN \
                                 new identity and floor without touching the entry at {other:?} at all. There is no \
                                 `gov floor-reanchor` any more -- identity is never transferred between paths; a \
                                 relocated checkout re-onboards instead, and the old entry is simply left inert"
                            ));
                        }
                    }
                }
                // P2-AR-0093 (AR92-C4): `bootstrap: true` -- this write is the document-claim adoption itself,
                // durably marked so `read_project_adoption_floor` can disclose it on every future read, not only
                // the one process that happens to observe "no local ledger yet" first (see
                // `FloorIdentityState::bootstrap_adopted`'s own doc).
                let _ = Self::write(root, doc_identity, doc_sequence, true);
                Ok(())
            }
            Some((local_identity, local_seq)) => {
                if doc_identity != local_identity {
                    return Err(format!(
                        "bound_project_identity {doc_identity:?} does not match this checkout's own established \
                         identity {local_identity:?}: this floor was minted for a DIFFERENT project or checkout \
                         (a clone reshaped and re-onboarded, or a subdirectory of this repository independently \
                         onboarded, AR86-C1/C2), not for this one"
                    ));
                }
                if doc_sequence < local_seq {
                    return Err(format!(
                        "floor_sequence {doc_sequence} is older than the highest sequence this checkout has \
                         already recorded ({local_seq}): an earlier, superseded floor was reinstated (AR86-C3) \
                         after a later, owner-authorised governed transition had already advanced it"
                    ));
                }
                if doc_sequence > local_seq {
                    // this checkout's OWN local ledger has fallen behind the tracked document it is reading --
                    // e.g. a collaborative checkout that never itself ran the CIT that advanced the floor, and
                    // received the new document through an ordinary `git pull` of a teammate's committed,
                    // owner-authorised change. That is forward, legitimate progress, never a rollback: ratchet
                    // the local high-water mark UP to match, and never let it be moved back down.
                    let _ = Self::write(root, &local_identity, doc_sequence, false);
                }
                Ok(())
            }
        }
    }
    /// **AR86-C6.** The rule set of the last floor THIS checkout itself saw fully authenticated, if any — read by
    /// `policy::PolicySet::load`'s reconstruction fallback (AR82-C2/AR84-C1) so a reconstruction derived from the
    /// repository's CURRENT on-disk shape is never weaker than what was last known good, even when the shape has
    /// since been arranged (an excluded directory name, a moved file) to make a fresh derivation miss something the
    /// authenticated record used to cover.
    fn last_known_rules(root: &Path) -> Vec<Value> {
        Self::read_full(root).map(|s| s.last_known_rules).unwrap_or_default()
    }
}

